const raw = $input.first().json;

const cq = raw.callbackQuery || raw.callback_query || raw;
const data = cq.data || raw.data || '';
const parts = String(data).split(':');
const actionRaw = (parts[0] || '').trim();
const contentId = (parts[1] || '').trim();

const action =
  actionRaw === 'approve' ? 'approved' :
  actionRaw === 'reject' ? 'rejected' :
  actionRaw === 'publish' ? 'publish' :
  actionRaw === 'cancel' ? 'cancel' :
  'unknown';

return [{
  json: {
    action,
    content_id: contentId,
    callback_query_id: String(cq.id || raw.id || ''),
    chat_id: cq.message?.chat?.id || raw.message?.chat?.id || '',
    message_id: cq.message?.message_id || ''
  }
}];

const item = $input.first();
const binary = item.binary?.data;

if (!binary) {
  throw new Error('Binary data bulunamadi');
}

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = Buffer.from(buffer).toString('base64');

return [{
  json: {
    ...item.json,
    image_base64: base64,
    content_id: $('Callback Parse').first().json.content_id
  }
}];

const d = $input.first().json;

const LINKEDIN_CHANNEL_ID = '6a6081ace2638b94d7b2a36b';
const INSTAGRAM_CHANNEL_ID = '6a608040e2638b94d7b29f29';

const hashtags = Array.isArray(d.hashtags)
  ? d.hashtags.join(' ')
  : String(d.hashtags || '');

const postText = `${d.content || ''}\n\n${hashtags}`.trim();

const platform = String(d.platform || '').toLowerCase();
const isInstagram = platform.includes('instagram');
const channelId = isInstagram ? INSTAGRAM_CHANNEL_ID : LINKEDIN_CHANNEL_ID;

if (!d.image_url) {
  throw new Error('image_url bos');
}

// Instagram zorunlu metadata; LinkedIn'de metadata yok
const metadataBlock = isInstagram
  ? `
      metadata: {
        instagram: {
          type: post
          shouldShareToFeed: true
        }
      }`
  : '';

const query = `
mutation CreatePost {
  createPost(
    input: {
      text: ${JSON.stringify(postText)}
      channelId: ${JSON.stringify(channelId)}
      schedulingType: automatic
      mode: shareNow
      ${metadataBlock}
      assets: [{ image: { url: ${JSON.stringify(d.image_url)} } }]
    }
  ) {
    ... on PostActionSuccess { post { id text } }
    ... on MutationError { message }
  }
}`;

return [{
  json: {
    query,
    content_id: String(d.id || $('Callback Parse').first().json.content_id),
    platform: d.platform,
    channelId,
    isInstagram
  }
}];

const raw = $input.first().json;
const msg = raw.message || {};
const text = String(msg.text || raw.text || '').trim();
const chatId = msg.chat?.id || raw.chat?.id || '';

if (!text.toLowerCase().startsWith('/yeni')) {
  return [{
    json: {
      ok: false,
      chat_id: chatId,
      error: 'Komut /yeni ile başlamalı.'
    }
  }];
}

const lines = text.split('\n').map((l) => l.trim()).filter(Boolean);
const map = {};

for (const line of lines.slice(1)) {
  const m = line.match(/^(platform|konu|topic|hedef|hedef kitle|target_audience|ton|tone)\s*:\s*(.+)$/i);
  if (!m) continue;
  const key = m[1].toLowerCase();
  const val = m[2].trim();
  if (key === 'konu' || key === 'topic') map.topic = val;
  else if (key === 'platform') map.platform = val;
  else if (key === 'hedef' || key === 'hedef kitle' || key === 'target_audience') map.target_audience = val;
  else if (key === 'ton' || key === 'tone') map.tone = val;
}

let platform = (map.platform || '').trim();
const p = platform.toLowerCase();
if (p.includes('linked')) platform = 'LinkedIn';
else if (p.includes('insta')) platform = 'Instagram';

const topic = map.topic || '';
const target_audience = map.target_audience || '';
const tone = map.tone || '';

const missing = [];
if (!platform) missing.push('platform');
if (!topic) missing.push('konu');
if (!target_audience) missing.push('hedef');
if (!tone) missing.push('ton');

if (missing.length) {
  return [{
    json: {
      ok: false,
      chat_id: chatId,
      error: `Eksik alan: ${missing.join(', ')}\n\nOrnek:\n/yeni\nplatform: LinkedIn\nkonu: ...\nhedef: ...\nton: ...`
    }
  }];
}

return [{
  json: {
    ok: true,
    chat_id: chatId,
    topic,
    platform,
    target_audience,
    tone
  }
}];

const raw = $input.first().json;

const cq = raw.callbackQuery || raw.callback_query;
const callbackData = cq?.data || raw.data || '';
const text = String(
  raw.message?.text || raw.text || ''
).trim();

let route = 'ignore';

if (callbackData && /^(approve|reject|publish|cancel):/i.test(String(callbackData))) {
  route = 'callback';
} else if (text.toLowerCase().startsWith('/yeni')) {
  route = 'yeni';
}

return [{
  json: {
    ...raw,
    route,
    // callback dalı eski Callback Parse'i bozmasın diye ham veriyi koru
  }
}];
